import{R as e,e as o,f as r,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Xero","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/xero.md","filePath":"integrations/crm/xero.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/xero.md"};function a(l,t,s,g,h,c){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="xero" tabindex="-1">Xero <a class="header-anchor" href="#xero" aria-label="Permalink to &quot;Xero&quot;">​</a></h1><p>Follow the below steps to connect to the Xero API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Xero as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-xero-api" tabindex="-1">Step 2. Connect to the Xero API <a class="header-anchor" href="#step-2-connect-to-the-xero-api" aria-label="Permalink to &quot;Step 2. Connect to the Xero API&quot;">​</a></h3><ol><li>Go to <a href="https://developer.xero.com/" target="_blank">Xero Developer Portal</a> and login to your account.</li><li>Navigate to <strong>My Apps</strong>.</li><li>Click the <strong>New App</strong> button.</li><li>Select <strong>Web App</strong>.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Navigate to <strong>Configuration</strong>.</li><li>Click the <strong>Generate a Secret</strong> button.</li><li>Copy the <strong>Client ID</strong> from Xero and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Xero and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Xero, where you must approve Formie to access your Xero account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(i,[["render",a]]);export{p as __pageData,m as default};
